  1	package hotel.reservations;
  2	
  3	import hotel.documents.ReservationReceipt;
  4	import hotel.rooms.Room;
  5	import hotel.rooms.Rooms;
  6	import java.math.BigDecimal;
  7	import java.util.ArrayList;
  8	import java.util.List;
  9	
 10	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 11	public final class ReservationService {
 12	
 13	    private final Rooms rooms;
 14	    private final ReservationStore store;
 15	    private final PriceCalculator priceCalculator;
 16	    private final List<ReservationEventListener> listeners;
 17	
 18	    public ReservationService(Rooms rooms, ReservationStore store, PriceCalculator priceCalculator) {
 19	        this.rooms = rooms;
 20	        this.store = store;
 21	        this.priceCalculator = priceCalculator;
 22	        this.listeners = new ArrayList<>();
 23	    }
 24	
 25	    public void addListener(ReservationEventListener listener) {
 26	        listeners.add(listener);
 27	    }
 28	
 29	    public synchronized Reservation create(NewReservation request) {
 30	        if (!request.checkOut().isAfter(request.checkIn())) {
 31	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 32	        }
 33	        if (request.guests() < 1) {
 34	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 35	        }
 36	        Room room = rooms.find(request.roomNumber())
 37	                .orElseThrow(() -> new HotelException(
 38	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 39	        if (request.guests() > room.capacity()) {
 40	            throw new HotelException(
 41	                    ErrorCode.CAPACITY_EXCEEDED,
 42	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 43	        }
 44	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 45	            throw new HotelException(
 46	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 47	        }
 48	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
 49	        return store.add(request, price);
 50	    }
 51	
 52	    public Reservation find(long reservationId) {
 53	        return store.find(reservationId)
 54	                .orElseThrow(() -> new HotelException(
 55	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 56	    }
 57	
 58	    /** The guest paid: the reservation is confirmed and notifications are sent. */
 59	    public synchronized Reservation confirm(long reservationId) {
 60	        Reservation reservation = find(reservationId);
 61	        if (reservation.status() != ReservationStatus.PENDING) {
 62	            throw notAllowed(reservation, "confirm");
 63	        }
 64	        reservation.confirmPayment();
 65	        store.update(reservation);
 66	        for (ReservationEventListener listener : listeners) {
 67	            listener.onReservationConfirmed(reservation);
 68	        }
 69	        return reservation;
 70	    }
 71	
 72	    /**
 73	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 74	     * reservation was never paid, so nothing comes back).
 75	     */
 76	    public synchronized Reservation cancel(long reservationId) {
 77	        Reservation reservation = find(reservationId);
 78	        if (reservation.status() != ReservationStatus.PENDING
 79	                && reservation.status() != ReservationStatus.CONFIRMED) {
 80	            throw notAllowed(reservation, "cancel");
 81	        }
 82	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
 83	        BigDecimal refund = switch (reservation.ratePlan()) {
 84	            case STANDARD -> reservation.amountPaid();
 85	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
 86	        };
 87	        reservation.cancel(refund);
 88	        store.update(reservation);
 89	        if (wasConfirmed) {
 90	            for (ReservationEventListener listener : listeners) {
 91	                listener.onReservationCancelled(reservation);
 92	            }
 93	        }
 94	        return reservation;
 95	    }
 96	
 97	    public synchronized Reservation checkIn(long reservationId) {
 98	        Reservation reservation = find(reservationId);
 99	        if (reservation.status() != ReservationStatus.CONFIRMED) {
100	            throw notAllowed(reservation, "check in");
101	        }
102	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
103	        store.update(reservation);
104	        return reservation;
105	    }
106	
107	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
108	    public synchronized ReservationReceipt checkOut(long reservationId) {
109	        Reservation reservation = find(reservationId);
110	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
111	            throw notAllowed(reservation, "check out");
112	        }
113	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
114	        store.update(reservation);
115	        return new ReservationReceipt(reservation, roomOf(reservation));
116	    }
117	
118	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
119	    public ReservationReceipt receiptCopy(long reservationId) {
120	        Reservation reservation = find(reservationId);
121	        if (!reservation.isPaid()) {
122	            throw notAllowed(reservation, "issue a receipt for");
123	        }
124	        return new ReservationReceipt(reservation, roomOf(reservation));
125	    }
126	
127	    private Room roomOf(Reservation reservation) {
128	        return rooms.find(reservation.roomNumber()).orElseThrow();
129	    }
130	
131	    private static HotelException notAllowed(Reservation reservation, String operation) {
132	        return new HotelException(
133	                ErrorCode.OPERATION_NOT_ALLOWED,
134	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
135	    }
136	}
  1	package hotel;
  2	
  3	import hotel.messages.EmailSender;
  4	import hotel.messages.SentMessages;
  5	import hotel.reports.OccupancyReport;
  6	import hotel.reports.RevenueReport;
  7	import hotel.reservations.FinanceNotifier;
  8	import hotel.reservations.GovernanceNotifier;
  9	import hotel.reservations.GuestNotifier;
 10	import hotel.reservations.PriceCalculator;
 11	import hotel.reservations.ReservationService;
 12	import hotel.reservations.ReservationStore;
 13	import hotel.rooms.Rooms;
 14	import hotel.web.HttpApi;
 15	import io.javalin.Javalin;
 16	import javax.sql.DataSource;
 17	
 18	/** Puts the inn's pieces together and runs the HTTP server. */
 19	public final class Hotel {
 20	
 21	    private final Javalin server;
 22	
 23	    public Hotel(DataSource dataSource) {
 24	        Rooms rooms = new Rooms(dataSource);
 25	        ReservationStore store = new ReservationStore(dataSource);
 26	        SentMessages sentMessages = new SentMessages(dataSource);
 27	        EmailSender emailSender = new EmailSender(sentMessages);
 28	        ReservationService reservations = new ReservationService(rooms, store, new PriceCalculator());
 29	        reservations.addListener(new GuestNotifier(emailSender, rooms));
 30	        reservations.addListener(new GovernanceNotifier(emailSender));
 31	        reservations.addListener(new FinanceNotifier(emailSender));
 32	        HttpApi api = new HttpApi(
 33	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
 34	        this.server = api.server();
 35	    }
 36	
 37	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
 38	    public int start(int port) {
 39	        server.start(port);
 40	        return server.port();
 41	    }
 42	
 43	    public void stop() {
 44	        server.stop();
 45	    }
 46	
 47	    public static void main(String[] args) {
 48	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 49	        Database database = new Database(System.getenv());
 50	        new Hotel(database.dataSource()).start(port);
 51	    }
 52	}
  1	package hotel.messages;
  2	
  3	/** Sends e-mails to guests. Every e-mail sent is kept in the list of sent messages. */
  4	public final class EmailSender {
  5	
  6	    private final SentMessages sentMessages;
  7	
  8	    public EmailSender(SentMessages sentMessages) {
  9	        this.sentMessages = sentMessages;
 10	    }
 11	
 12	    public Message send(String to, String subject, String body) {
 13	        return sentMessages.add("EMAIL", to, subject, body);
 14	    }
 15	}
 16	package hotel.documents;
 17	
 18	import java.math.BigDecimal;
 19	import java.time.LocalDate;
 20	import java.time.format.DateTimeFormatter;
 21	import java.util.Locale;
 22	
 23	/** How money and dates are written in the texts the guest reads (Brazilian Portuguese). */
 24	public final class TextFormat {
 25	
 26	    private static final Locale BRAZIL = Locale.forLanguageTag("pt-BR");
 27	    private static final DateTimeFormatter BRAZILIAN_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 28	
 29	    private TextFormat() {
 30	    }
 31	
 32	    public static String money(BigDecimal amount) {
 33	        return "R$ " + String.format(BRAZIL, "%,.2f", amount);
 34	    }
 35	
 36	    public static String date(LocalDate date) {
 37	        return BRAZILIAN_DATE.format(date);
 38	    }
 39	}

