  9	import hotel.reservations.GuestNotifier;
 10	import hotel.reservations.PriceCalculator;
 11	import hotel.reservations.ReservationService;
 12	import hotel.reservations.ReservationStore;
 13	import hotel.rooms.Rooms;
 14	import hotel.web.HttpApi;
 15	import io.javalin.Javalin;
 16	import javax.sql.DataSource;
 17	
 18	/** Puts the inn's pieces together and runs the HTTP server. */
 19	public final class Hotel {
 20	
 21	    private final Javalin server;
 22	
 23	    public Hotel(DataSource dataSource) {
 24	        Rooms rooms = new Rooms(dataSource);
 25	        ReservationStore store = new ReservationStore(dataSource);
 26	        SentMessages sentMessages = new SentMessages(dataSource);
 27	        EmailSender emailSender = new EmailSender(sentMessages);
 28	        ReservationService reservations = new ReservationService(rooms, store, new PriceCalculator());
 29	        reservations.addListener(new GuestNotifier(emailSender, rooms));
 30	        reservations.addListener(new GovernanceNotifier(emailSender));
 31	        reservations.addListener(new FinanceNotifier(emailSender));
 32	        HttpApi api = new HttpApi(
 33	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
 34	        this.server = api.server();
 35	    }
 36	
 37	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
 38	    public int start(int port) {
 39	        server.start(port);
 40	        return server.port();
 41	    }
 42	
 43	    public void stop() {
 44	        server.stop();
 45	    }
 46	
 47	    public static void main(String[] args) {
 48	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 49	        Database database = new Database(System.getenv());
 50	        new Hotel(database.dataSource()).start(port);
 51	    }
 52	}
